        int totalTime = 0;
        for (int v : adj[u]) {
            if (v != p) {
                int childTime = dfs(v, u, adj, hasApple);
                if (childTime > 0 || hasApple[v]) {
                    totalTime += childTime + 2;
                }
            }
        }
        return totalTime;
